-- 0099: seed DHET-listed public universities and TVET colleges into the existing
-- route-provider directory. Directory presence is deliberately not promoted to
-- verified application routes, open programmes, deadlines, eligibility or partnerships.
-- This migration adds 76 provider directory entries only; it does not create programmes.
BEGIN;

-- Idempotently add the separate DHET TVET directory source anchor. Keep last_verified_at
-- NULL; a directory record in code is not the same as a live source-health confirmation.
INSERT INTO public.source_authorities (
  source_key, source_name, source_type, base_url, default_confidence_band,
  verification_required, last_verified_at, verification_notes
) VALUES (
  'dhet_tvet_directory',
  'DHET TVET Colleges Directory',
  'government_institution_list',
  'https://www.dhet.gov.za/SitePages/TVETlinks.aspx',
  'C',
  true,
  NULL,
  'Official DHET directory anchor. This source records provider-list entries only; revalidate the page and each published website URL before use. It does not prove current programme intake, application route, deadline, eligibility, accreditation scope or partnership.'
)
ON CONFLICT (source_key) DO NOTHING;

DO $preflight$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.source_authorities WHERE source_key = 'dhet_universities'
  ) THEN
    RAISE EXCEPTION 'Missing existing DHET university source anchor dhet_universities; review source migration order before seeding';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.source_authorities WHERE source_key = 'dhet_tvet_directory'
  ) THEN
    RAISE EXCEPTION 'Missing DHET TVET source anchor after idempotent insert';
  END IF;
END
$preflight$;

