INSERT INTO public.route_providers (
  provider_key, provider_name, provider_type, province, base_url, source_authority_id,
  default_confidence_band, verification_status, public_safe,
  private_provider_requires_accreditation_check, notes, metadata
)
SELECT
  d.provider_key,
  d.provider_name,
  d.provider_type,
  d.province,
  d.base_url,
  sa.id,
  'C',
  'NEEDS_REVIEW',
  false,
  false,
  'Listed in a DHET directory only. Website, programme, current intake, deadline, eligibility and application route require independent verification; no institutional partnership or submission capability is implied.',
  d.seed_metadata
FROM source_rows d
JOIN public.source_authorities sa ON sa.source_key = d.source_key
ON CONFLICT (provider_key) DO UPDATE SET
  provider_name = EXCLUDED.provider_name,
  provider_type = EXCLUDED.provider_type,
  province = COALESCE(public.route_providers.province, EXCLUDED.province),
  base_url = COALESCE(public.route_providers.base_url, EXCLUDED.base_url),
  source_authority_id = COALESCE(public.route_providers.source_authority_id, EXCLUDED.source_authority_id),
  metadata = public.route_providers.metadata || EXCLUDED.metadata,
  updated_at = now();

-- Fail closed if the full provider directory seed is not present.
DO $verify$
DECLARE
  v_universities integer;
  v_tvet integer;
BEGIN
  SELECT count(*) INTO v_universities
  FROM public.route_providers
  WHERE provider_key LIKE 'dhet_university_%'
    AND provider_type = 'UNIVERSITY'
    AND verification_status = 'NEEDS_REVIEW'
    AND public_safe = false
    AND metadata ? 'dhet_directory_seed';

  SELECT count(*) INTO v_tvet
  FROM public.route_providers
  WHERE provider_key LIKE 'dhet_tvet_%'
    AND provider_type = 'TVET'
    AND verification_status = 'NEEDS_REVIEW'
    AND public_safe = false
    AND metadata ? 'dhet_directory_seed';

  IF v_universities <> 26 THEN
    RAISE EXCEPTION 'Expected 26 DHET public-university directory records; found %', v_universities;
  END IF;
  IF v_tvet <> 50 THEN
    RAISE EXCEPTION 'Expected 50 DHET TVET directory records; found %', v_tvet;
  END IF;
END
$verify$;

COMMIT;
